<?php

namespace App\Http\Controllers;

use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\View\View;

class LecturerManagementController extends Controller
{
    public function classes(Request $request): View { return view('dosen-manajemen', ['section'=>'classes','classes'=>DB::table('classrooms')->where('lecturer_id',$request->user()->id)->latest()->get(),'students'=>DB::table('users')->where('role','student')->orderBy('name')->get()]); }
    public function storeClass(Request $request): RedirectResponse { $d=$request->validate(['name'=>['required','string','max:120'],'code'=>['required','alpha_dash','max:30','unique:classrooms'],'semester'=>['nullable','string','max:80']]); DB::table('classrooms')->insert([...$d,'lecturer_id'=>$request->user()->id,'created_at'=>now(),'updated_at'=>now()]); return back()->with('success','Kelas dibuat.'); }
    public function addMember(Request $request): RedirectResponse { $d=$request->validate(['classroom_id'=>['required','exists:classrooms,id'],'user_id'=>['required','exists:users,id'],'group_name'=>['nullable','string','max:80']]); DB::table('classroom_members')->updateOrInsert(['classroom_id'=>$d['classroom_id'],'user_id'=>$d['user_id']],['group_name'=>$d['group_name']??null,'updated_at'=>now(),'created_at'=>now()]); return back()->with('success','Mahasiswa/kelompok diperbarui.'); }
    public function attendance(Request $request): View { return view('dosen-presensi',['classes'=>DB::table('classrooms')->where('lecturer_id',$request->user()->id)->get(),'sessions'=>DB::table('attendance_sessions')->leftJoin('classrooms','classrooms.id','=','attendance_sessions.classroom_id')->select('attendance_sessions.*','classrooms.name as classroom_name')->orderByDesc('opens_at')->get()]); }
    public function storeAttendance(Request $request): RedirectResponse { $d=$request->validate(['classroom_id'=>['nullable','exists:classrooms,id'],'module'=>['required','string','max:120'],'code'=>['required','string','max:40'],'opens_at'=>['required','date'],'closes_at'=>['required','date','after:opens_at'],'student_name'=>['required','array','size:50'],'status'=>['required','array','size:50']]); $sessionId=DB::table('attendance_sessions')->insertGetId(['classroom_id'=>$d['classroom_id']??null,'module'=>$d['module'],'code'=>strtoupper($d['code']),'opens_at'=>$d['opens_at'],'closes_at'=>$d['closes_at'],'created_at'=>now(),'updated_at'=>now()]); foreach($d['student_name'] as $i=>$name) DB::table('attendance_manual_entries')->insert(['attendance_session_id'=>$sessionId,'student_name'=>$name,'status'=>$d['status'][$i],'created_at'=>now(),'updated_at'=>now()]); DB::table('announcements')->insert(['lecturer_id'=>$request->user()->id,'classroom_id'=>$d['classroom_id']??null,'title'=>'Token Presensi: '.$d['module'],'body'=>'Token presensi SIAKAD untuk '.$d['module'].': '.strtoupper($d['code']).'. Silakan salin token ini dan masukkan ke SIAKAD masing-masing sebelum sesi ditutup.','published_at'=>now(),'created_at'=>now(),'updated_at'=>now()]); return back()->with('success','Token dan presensi manual berhasil diterbitkan.'); }
    public function announcements(Request $request): View { return view('dosen-manajemen',['section'=>'announcements','classes'=>DB::table('classrooms')->where('lecturer_id',$request->user()->id)->get(),'announcements'=>DB::table('announcements')->where('lecturer_id',$request->user()->id)->latest()->get()]); }
    public function storeAnnouncement(Request $request): RedirectResponse { $d=$request->validate(['classroom_id'=>['nullable','exists:classrooms,id'],'title'=>['required','string','max:160'],'body'=>['required','string','max:5000']]); DB::table('announcements')->insert([...$d,'lecturer_id'=>$request->user()->id,'published_at'=>now(),'created_at'=>now(),'updated_at'=>now()]); return back()->with('success','Pengumuman diterbitkan.'); }
    public function trainerKit(): View { for($i=1;$i<=8;$i++) DB::table('trainer_kits')->updateOrInsert(['module_number'=>$i],['title'=>'Trainer Kit '.$i,'status'=>'draft','updated_at'=>now(),'created_at'=>now()]); return view('dosen-manajemen',['section'=>'trainer','kits'=>DB::table('trainer_kits')->orderBy('module_number')->get()]); }
    public function updateTrainerKit(Request $request, int $kit): RedirectResponse { $d=$request->validate(['title'=>['required','string','max:120'],'status'=>['required','in:draft,available,maintenance'],'notes'=>['nullable','string','max:2000']]); DB::table('trainer_kits')->where('id',$kit)->update([...$d,'updated_at'=>now()]); return back()->with('success','Status trainer kit diperbarui.'); }
    public function questions(Request $request): View { return view('dosen-manajemen',['section'=>'questions','questions'=>DB::table('question_bank')->where('lecturer_id',$request->user()->id)->latest()->get()]); }
    public function storeQuestion(Request $request): RedirectResponse { $d=$request->validate(['module'=>['required','string','max:120'],'question'=>['required','string','max:2000'],'options_text'=>['required','string','max:2000'],'correct_answer'=>['required','string','max:255'],'points'=>['required','integer','min:1','max:100']]); $options=array_values(array_filter(array_map('trim',preg_split('/\R/',$d['options_text'])))); DB::table('question_bank')->insert(['lecturer_id'=>$request->user()->id,'module'=>$d['module'],'question'=>$d['question'],'options'=>json_encode($options),'correct_answer'=>$d['correct_answer'],'points'=>$d['points'],'created_at'=>now(),'updated_at'=>now()]); return back()->with('success','Soal ditambahkan.'); }
    public function monitoring(): View { return view('dosen-manajemen',['section'=>'monitoring','students'=>DB::table('users')->where('role','student')->leftJoin('reports','reports.user_id','=','users.id')->leftJoin('quiz_attempts','quiz_attempts.user_id','=','users.id')->select('users.name','users.email',DB::raw('count(distinct reports.id) as reports_count'),DB::raw('count(distinct quiz_attempts.id) as quizzes_count'))->groupBy('users.id','users.name','users.email')->get()]); }
}
